let drops = [];
let splashes = [];
const NUM_DROPS = 350;
const AVOID_RADIUS = 90;

function setup() {
  createCanvas(640, 400);
  for (let i = 0; i < NUM_DROPS; i++) {
    drops.push(createDrop(true));
  }
}

function createDrop(initial = false) {
  return {
    x: random(-50, width + 50),
    y: initial ? random(0, height) : random(-60, -10),
    vx: 0,
    vy: random(5, 10),
    baseSpeed: random(5, 10),
    len: random(10, 22),
    thickness: random(1, 2.5),
    opacity: random(140, 240)
  };
}

function addSplash(x, y) {
  if (splashes.length < 50) {
    splashes.push({
      x: x,
      y: y,
      r: 2,
      maxR: random(10, 25),
      opacity: 200
    });
  }
}

function draw() {
  background(12, 18, 30);

  // Subtle umbrella / repeller field glow around mouse
  noFill();
  stroke(100, 180, 255, 30);
  strokeWeight(12);
  circle(mouseX, mouseY, AVOID_RADIUS * 2);
  stroke(140, 210, 255, 90);
  strokeWeight(2);
  circle(mouseX, mouseY, AVOID_RADIUS * 2);

  // Center indicator for mouse
  fill(180, 225, 255, 200);
  noStroke();
  circle(mouseX, mouseY, 8);

  // Update and draw splashes
  for (let i = splashes.length - 1; i >= 0; i--) {
    let s = splashes[i];
    noFill();
    stroke(160, 210, 255, s.opacity);
    strokeWeight(1.2);
    ellipse(s.x, s.y, s.r * 2, s.r * 0.8);
    s.r += 1.2;
    s.opacity -= 8;
    if (s.opacity <= 0 || s.r >= s.maxR) {
      splashes.splice(i, 1);
    }
  }

  // Update and draw rain drops
  for (let i = 0; i < drops.length; i++) {
    let d = drops[i];

    // Repulsion from mouse
    let dx = d.x - mouseX;
    let dy = d.y - mouseY;
    let distSq = dx * dx + dy * dy;
    let rSq = AVOID_RADIUS * AVOID_RADIUS;

    if (distSq < rSq && distSq > 0.01) {
      let distance = sqrt(distSq);
      let nx = dx / distance;
      let ny = dy / distance;
      let force = (AVOID_RADIUS - distance) / AVOID_RADIUS;

      // Push outward rapidly, biasing horizontal evasion
      d.vx += nx * force * 3.5;
      d.vy += ny * force * 1.5;

      // Tangential velocity around the boundary
      let side = nx >= 0 ? 1 : -1;
      d.vx += side * 1.2;

      if (random(1) < 0.1) {
        addSplash(d.x, d.y);
      }
    }

    // Natural downward motion and drag
    d.vy = lerp(d.vy, d.baseSpeed, 0.08);
    d.vx = lerp(d.vx, 0, 0.05);

    d.x += d.vx;
    d.y += d.vy;

    // Draw rain drop
    stroke(170, 215, 255, d.opacity);
    strokeWeight(d.thickness);
    let tailX = d.x - d.vx * 1.2;
    let tailY = d.y - d.len - d.vy * 0.5;
    line(d.x, d.y, tailX, tailY);

    // Reset when exiting screen
    if (d.y > height + 10 || d.x < -80 || d.x > width + 80) {
      if (d.y > height && random(1) < 0.3) {
        addSplash(d.x, height - 2);
      }
      drops[i] = createDrop(false);
    }
  }
}
